import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"5.2 熔断器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-2-rong-duan-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-2-rong-duan-qi.md","lastUpdated":1793095197000}'),o={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-2-rong-duan-qi.md"};function e(s,a,r,d,c,h){return l(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="_5-2-熔断器" tabindex="-1">5.2 熔断器 <a class="header-anchor" href="#_5-2-熔断器" aria-label="Permalink to &quot;5.2 熔断器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>熔断器是最简单、最古老的保护电器——&quot;电流太大就烧断自己,切断电路&quot;。它是<strong>短路保护</strong>的主力,家里的保险丝、配电箱里的熔芯都是它。这一节讲原理、类型、型号和选用。</p><h2 id="一、作用-短路保护" tabindex="-1">一、作用:短路保护 <a class="header-anchor" href="#一、作用-短路保护" aria-label="Permalink to &quot;一、作用:短路保护&quot;">​</a></h2><p>熔断器串联在电路中,当电路发生<strong>短路</strong>或严重过载时,电流急剧增大,熔体发热<strong>熔断</strong>,切断电路,保护设备和线路。</p><blockquote><p>⚠️ 重点:<strong>熔断器是短路保护</strong>,一般<strong>不能作电动机的过载保护</strong>(电动机启动电流大,熔断器会误断)——过载保护靠热继电器(5.5 节)。</p></blockquote><h2 id="二、工作原理" tabindex="-1">二、工作原理 <a class="header-anchor" href="#二、工作原理" aria-label="Permalink to &quot;二、工作原理&quot;">​</a></h2><p>熔体(保险丝)是低熔点金属(铅、锡合金或银、铜丝):</p><ul><li>正常工作时,电流小,熔体不发热(或散热足够),保持完好;</li><li>短路时电流猛增,熔体发热量 <code>Q = I²Rt</code> 剧增(电流平方!),温度骤升到熔点,<strong>熔断</strong>切断电路。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常:  电流小 ───────[熔体]───────► 负载   → 电路正常</span></span>
<span class="line"><span>短路:  电流大 → 熔体迅速熔断,电路断开  → 设备被保护</span></span></code></pre></div><h2 id="三、类型与型号" tabindex="-1">三、类型与型号 <a class="header-anchor" href="#三、类型与型号" aria-label="Permalink to &quot;三、类型与型号&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型型号</th></tr></thead><tbody><tr><td>瓷插式</td><td>老式,用于小电流照明线路</td><td>RC1A</td></tr><tr><td>螺旋式</td><td>带熔断指示,分断能力较高</td><td>RL1、RL6</td></tr><tr><td>管式(有填料)</td><td>分断能力高,用于大电流配电</td><td>RT0、RT14</td></tr><tr><td>快速熔断器</td><td>动作快,保护半导体元件</td><td>RS0、RS3</td></tr></tbody></table><p><strong>型号含义</strong>(以 RL1-15 为例):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R  L  1 - 15</span></span>
<span class="line"><span>│  │     └─ 熔断器额定电流(A)</span></span>
<span class="line"><span>│  └─ 设计序号</span></span>
<span class="line"><span>└─ 类型代号:R=熔断器;L=螺旋式;C=瓷插式;T=有填料管式;S=快速</span></span></code></pre></div><blockquote><p>💡 记住<strong>第一个字母 R 代表熔断器</strong>就够应付大部分题型;再记 L(螺旋)、T(管式)。</p></blockquote><h2 id="四、选用原则" tabindex="-1">四、选用原则 <a class="header-anchor" href="#四、选用原则" aria-label="Permalink to &quot;四、选用原则&quot;">​</a></h2><ol><li><strong>额定电压</strong>:等于或大于电路额定电压;</li><li><strong>额定电流</strong>:熔体电流 ≥ 电路正常工作电流(留适当余量);</li><li><strong>分级配合</strong>:同一供电链路上,越靠近电源的熔断器额定电流越大(上级熔断,下级才能先断),保证<strong>选择性</strong>;</li><li>保护电动机时,熔体电流要按电动机启动电流考虑,不能按额定电流简单选取。</li></ol><h2 id="五、使用注意事项" tabindex="-1">五、使用注意事项 <a class="header-anchor" href="#五、使用注意事项" aria-label="Permalink to &quot;五、使用注意事项&quot;">​</a></h2><ul><li>更换熔体时必须<strong>断电</strong>后进行,禁止带电换保险;</li><li>熔体烧断后,先<strong>查明原因</strong>(短路还是过载),排除故障再更换,<strong>不得用铜丝铁丝代替</strong>保险丝;</li><li>熔断器应与电路匹配,过大不起保护作用,过小频繁熔断。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>用铜丝代替熔断器熔体是错误且危险的</strong>(铜丝熔点高、熔断特性差,短路时不能可靠断开)。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 熔断器 = <strong>短路保护</strong>。</li><li>✅ 熔体电流选择与分级配合(靠近电源的额定电流更大)。</li><li>✅ <strong>禁止用铜丝、铁丝代替熔体</strong>。</li><li>⚠️ 易混点:熔断器不能代替热继电器做电动机过载保护。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>熔断器靠&quot;大电流熔断熔体&quot;实现短路保护。</li><li>型号第一个字母 R;类型有瓷插、螺旋、管式、快速。</li><li>选用要分级配合,更换前先断电、先查故障。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)熔断器的作用是短路保护。( )</li><li>(判断)熔断器烧断后,可以用铜丝代替熔体继续使用。( )</li><li>(单选)熔断器型号的第一个字母 R 表示()。 A. 热继电器　B. 熔断器　C. 继电器　D. 电阻器</li><li>(判断)同一供电线路中,靠近电源侧的熔断器额定电流应比下级大,以保证选择性。( )</li><li>(单选)电动机的过载保护一般不用熔断器,而用()。 A. 热继电器　B. 刀开关　C. 按钮　D. 漏电保护器</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。熔断器主要承担短路保护。</li><li><strong>×</strong>。严禁用铜丝、铁丝代替熔体,非常危险。</li><li><strong>B</strong>。R 是熔断器代号(RC、RL、RT、RS)。</li><li><strong>√</strong>。分级配合才能选择性跳闸。</li><li><strong>A</strong>。过载保护用热继电器。</li></ol></details>`,27)])])}const u=t(o,[["render",e]]);export{p as __pageData,u as default};
